  "\nCREATE TABLE canvas_agent_messages (\n\tthread_id INTEGER NOT NULL, \n\trole VARCHAR(16) NOT NULL, \n\tcontent TEXT NOT NULL, \n\tsequence INTEGER NOT NULL, \n\tjob_id INTEGER, \n\tparameters JSON NOT NULL, \n\tid INTEGER NOT NULL, \n\tcreated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tupdated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tworkspace_id VARCHAR(32), \n\tPRIMARY KEY (id), \n\tCONSTRAINT uq_canvas_agent_messages_sequence UNIQUE (thread_id, sequence), \n\tFOREIGN KEY(thread_id) REFERENCES canvas_agent_threads (id) ON DELETE CASCADE, \n\tFOREIGN KEY(job_id) REFERENCES jobs (id) ON DELETE SET NULL, \n\tFOREIGN KEY(workspace_id) REFERENCES workspaces (id) ON DELETE RESTRICT\n)\n\n",
  "\nCREATE TABLE canvas_edges (\n\tcanvas_id INTEGER NOT NULL, \n\tedge_key VARCHAR(64) NOT NULL, \n\tsource_key VARCHAR(64) NOT NULL, \n\ttarget_key VARCHAR(64) NOT NULL, \n\tsource_handle VARCHAR(64), \n\ttarget_handle VARCHAR(64), \n\tdata JSON NOT NULL, \n\tid INTEGER NOT NULL, \n\tcreated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tupdated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tworkspace_id VARCHAR(32), \n\tPRIMARY KEY (id), \n\tCONSTRAINT uq_canvas_edges_key UNIQUE (canvas_id, edge_key), \n\tFOREIGN KEY(canvas_id) REFERENCES canvas_documents (id) ON DELETE CASCADE, \n\tFOREIGN KEY(workspace_id) REFERENCES workspaces (id) ON DELETE RESTRICT\n)\n\n",
  "\nCREATE TABLE canvas_nodes (\n\tcanvas_id INTEGER NOT NULL, \n\tnode_key VARCHAR(64) NOT NULL, \n\tnode_type VARCHAR(32) NOT NULL, \n\tx FLOAT NOT NULL, \n\ty FLOAT NOT NULL, \n\twidth FLOAT, \n\theight FLOAT, \n\tz_index INTEGER NOT NULL, \n\tparent_key VARCHAR(64), \n\tdata JSON NOT NULL, \n\tlocked BOOLEAN NOT NULL, \n\tid INTEGER NOT NULL, \n\tcreated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tupdated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tworkspace_id VARCHAR(32), \n\tPRIMARY KEY (id), \n\tCONSTRAINT uq_canvas_nodes_key UNIQUE (canvas_id, node_key), \n\tFOREIGN KEY(canvas_id) REFERENCES canvas_documents (id) ON DELETE CASCADE, \n\tFOREIGN KEY(workspace_id) REFERENCES workspaces (id) ON DELETE RESTRICT\n)\n\n",
  "\nCREATE TABLE creation_artifacts (\n\tsession_id INTEGER NOT NULL, \n\tartifact_type VARCHAR(32) NOT NULL, \n\tversion INTEGER NOT NULL, \n\trevision INTEGER DEFAULT '0' NOT NULL, \n\tstatus VARCHAR(24) NOT NULL, \n\tcontent JSON NOT NULL, \n\tsource_job_id INTEGER, \n\tid INTEGER NOT NULL, \n\tcreated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tupdated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tworkspace_id VARCHAR(32), \n\tPRIMARY KEY (id), \n\tCONSTRAINT uq_creation_artifacts_version UNIQUE (session_id, artifact_type, version), \n\tFOREIGN KEY(session_id) REFERENCES creation_sessions (id) ON DELETE CASCADE, \n\tFOREIGN KEY(source_job_id) REFERENCES jobs (id) ON DELETE SET NULL, \n\tFOREIGN KEY(workspace_id) REFERENCES workspaces (id) ON DELETE RESTRICT\n)\n\n",
  "\nCREATE TABLE creation_messages (\n\tsession_id INTEGER NOT NULL, \n\trole VARCHAR(16) NOT NULL, \n\tmessage_type VARCHAR(32) NOT NULL, \n\tcontent TEXT NOT NULL, \n\tsequence INTEGER NOT NULL, \n\tjob_id INTEGER, \n\tparameters JSON NOT NULL, \n\tid INTEGER NOT NULL, \n\tcreated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tupdated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tworkspace_id VARCHAR(32), \n\tPRIMARY KEY (id), \n\tCONSTRAINT uq_creation_messages_sequence UNIQUE (session_id, sequence), \n\tFOREIGN KEY(session_id) REFERENCES creation_sessions (id) ON DELETE CASCADE, \n\tFOREIGN KEY(job_id) REFERENCES jobs (id) ON DELETE SET NULL, \n\tFOREIGN KEY(workspace_id) REFERENCES workspaces (id) ON DELETE RESTRICT\n)\n\n",
  "\nCREATE TABLE edit_projects (\n\tproject_id INTEGER NOT NULL, \n\towner_id INTEGER NOT NULL, \n\ttitle VARCHAR(160) NOT NULL, \n\tcreation_request_id VARCHAR(128) NOT NULL, \n\tcreation_request_hash VARCHAR(64) NOT NULL, \n\tsource_episode_id INTEGER, \n\tframe_rate INTEGER NOT NULL, \n\trevision INTEGER DEFAULT '0' NOT NULL, \n\tfingerprint VARCHAR(64) NOT NULL, \n\tdocument JSON, \n\tsource_evidence JSON DEFAULT '{}' NOT NULL, \n\tid INTEGER NOT NULL, \n\tcreated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tupdated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tworkspace_id VARCHAR(32), \n\tPRIMARY KEY (id), \n\tCONSTRAINT uq_edit_projects_creation UNIQUE (project_id, creation_request_id), \n\tFOREIGN KEY(project_id) REFERENCES projects (id) ON DELETE CASCADE, \n\tFOREIGN KEY(owner_id) REFERENCES users (id), \n\tFOREIGN KEY(source_episode_id) REFERENCES episodes (id) ON DELETE SET NULL, \n\tFOREIGN KEY(workspace_id) REFERENCES workspaces (id) ON DELETE RESTRICT\n)\n\n",
  "\nCREATE TABLE episode_edit_drafts (\n\tepisode_id INTEGER NOT NULL, \n\trevision INTEGER DEFAULT '0' NOT NULL, \n\tfingerprint VARCHAR(64) NOT NULL, \n\tdocument JSON NOT NULL, \n\tid INTEGER NOT NULL, \n\tcreated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tupdated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tworkspace_id VARCHAR(32), \n\tPRIMARY KEY (id), \n\tCONSTRAINT uq_episode_edit_drafts_episode UNIQUE (episode_id), \n\tFOREIGN KEY(episode_id) REFERENCES episodes (id) ON DELETE CASCADE, \n\tFOREIGN KEY(workspace_id) REFERENCES workspaces (id) ON DELETE RESTRICT\n)\n\n",
  "\nCREATE TABLE episode_edit_receipts (\n\tepisode_id INTEGER NOT NULL, \n\trequest_id VARCHAR(128) NOT NULL, \n\trequest_hash VARCHAR(64) NOT NULL, \n\tresponse JSON NOT NULL, \n\tid INTEGER NOT NULL, \n\tcreated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tupdated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tworkspace_id VARCHAR(32), \n\tPRIMARY KEY (id), \n\tCONSTRAINT uq_episode_edit_receipts_request UNIQUE (episode_id, request_id), \n\tFOREIGN KEY(episode_id) REFERENCES episodes (id) ON DELETE CASCADE, \n\tFOREIGN KEY(workspace_id) REFERENCES workspaces (id) ON DELETE RESTRICT\n)\n\n",
  "\nCREATE TABLE episode_planning_records (\n\tepisode_id INTEGER NOT NULL, \n\texecution_epoch VARCHAR(128) NOT NULL, \n\trevision INTEGER NOT NULL, \n\tfingerprint VARCHAR(64) NOT NULL, \n\tsnapshot JSON NOT NULL, \n\tanalysis_snapshot JSON, \n\tid INTEGER NOT NULL, \n\tcreated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tupdated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tworkspace_id VARCHAR(32), \n\tPRIMARY KEY (id), \n\tCONSTRAINT uq_episode_planning_revision UNIQUE (episode_id, execution_epoch, revision), \n\tCONSTRAINT ck_episode_planning_revision CHECK (revision > 0), \n\tCONSTRAINT ck_episode_planning_fingerprint CHECK (length(fingerprint) = 64), \n\tFOREIGN KEY(episode_id) REFERENCES episodes (id) ON DELETE CASCADE, \n\tFOREIGN KEY(workspace_id) REFERENCES workspaces (id) ON DELETE RESTRICT\n)\n\n",
  "\nCREATE TABLE episode_production_plans (\n\tepisode_id INTEGER NOT NULL, \n\towner_id INTEGER NOT NULL, \n\tversion INTEGER NOT NULL, \n\tsource_type VARCHAR(24) DEFAULT 'manual' NOT NULL, \n\tparent_plan_id INTEGER, \n\tstatus VARCHAR(24) DEFAULT 'draft' NOT NULL, \n\tsource_script_revision INTEGER NOT NULL, \n\tprovider_model_id INTEGER, \n\tmodel_capability_snapshot JSON DEFAULT '{}' NOT NULL, \n\tparameters JSON DEFAULT '{}' NOT NULL, \n\ttotal_timeline_duration FLOAT DEFAULT '0' NOT NULL, \n\ttotal_generation_duration FLOAT DEFAULT '0' NOT NULL, \n\trevision INTEGER DEFAULT '0' NOT NULL, \n\tconfirmed_at DATETIME, \n\tid INTEGER NOT NULL, \n\tcreated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tupdated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tworkspace_id VARCHAR(32), \n\tPRIMARY KEY (id), \n\tCONSTRAINT uq_episode_production_plans_version UNIQUE (episode_id, version), \n\tFOREIGN KEY(episode_id) REFERENCES episodes (id) ON DELETE CASCADE, \n\tFOREIGN KEY(owner_id) REFERENCES users (id) ON DELETE RESTRICT, \n\tFOREIGN KEY(parent_plan_id) REFERENCES episode_production_plans (id) ON DELETE SET NULL, \n\tFOREIGN KEY(provider_model_id) REFERENCES provider_models (id) ON DELETE SET NULL, \n\tFOREIGN KEY(workspace_id) REFERENCES workspaces (id) ON DELETE RESTRICT\n)\n\n",
  "\nCREATE TABLE market_research_runs (\n\towner_id INTEGER NOT NULL, \n\tmarket VARCHAR(16) NOT NULL, \n\tregion VARCHAR(64) NOT NULL, \n\tplatforms JSON NOT NULL, \n\tgenres JSON NOT NULL, \n\taudience VARCHAR(128) NOT NULL, \n\ttime_range VARCHAR(16) NOT NULL, \n\tkeywords TEXT NOT NULL, \n\tstatus VARCHAR(16) NOT NULL, \n\tsources JSON NOT NULL, \n\treport JSON, \n\terror_message TEXT, \n\tselected_idea_index INTEGER, \n\tadopted_project_id INTEGER, \n\tjob_id INTEGER, \n\tid INTEGER NOT NULL, \n\tcreated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tupdated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tworkspace_id VARCHAR(32), \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(owner_id) REFERENCES users (id) ON DELETE CASCADE, \n\tFOREIGN KEY(adopted_project_id) REFERENCES projects (id) ON DELETE SET NULL, \n\tFOREIGN KEY(job_id) REFERENCES jobs (id) ON DELETE SET NULL, \n\tFOREIGN KEY(workspace_id) REFERENCES workspaces (id) ON DELETE RESTRICT\n)\n\n",
  "\nCREATE TABLE media_reservations (\n\tjob_id INTEGER NOT NULL, \n\tsize BIGINT NOT NULL, \n\tcreated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tupdated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tworkspace_id VARCHAR(32), \n\tPRIMARY KEY (job_id), \n\tCONSTRAINT ck_media_reservation_size CHECK (size >= 0), \n\tFOREIGN KEY(job_id) REFERENCES jobs (id) ON DELETE CASCADE, \n\tFOREIGN KEY(workspace_id) REFERENCES workspaces (id) ON DELETE RESTRICT\n)\n\n",
  "\nCREATE TABLE project_asset_links (\n\tproject_id INTEGER NOT NULL, \n\tasset_id INTEGER NOT NULL, \n\tlocal_slug VARCHAR(128) NOT NULL, \n\tproduction_data JSON DEFAULT '{}' NOT NULL, \n\tproduction_revision INTEGER DEFAULT '0' NOT NULL, \n\tproduction_archived BOOLEAN DEFAULT '0' NOT NULL, \n\tid INTEGER NOT NULL, \n\tcreated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tupdated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tworkspace_id VARCHAR(32), \n\tPRIMARY KEY (id), \n\tCONSTRAINT uq_project_asset_links_asset UNIQUE (project_id, asset_id), \n\tCONSTRAINT uq_project_asset_links_slug UNIQUE (project_id, local_slug), \n\tFOREIGN KEY(project_id) REFERENCES projects (id) ON DELETE CASCADE, \n\tFOREIGN KEY(asset_id) REFERENCES assets (id) ON DELETE CASCADE, \n\tFOREIGN KEY(workspace_id) REFERENCES workspaces (id) ON DELETE RESTRICT\n)\n\n",
  "\nCREATE TABLE project_media_links (\n\tproject_id INTEGER NOT NULL, \n\tmedia_file_id INTEGER NOT NULL, \n\tid INTEGER NOT NULL, \n\tcreated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tupdated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tworkspace_id VARCHAR(32), \n\tPRIMARY KEY (id), \n\tCONSTRAINT uq_project_media_links_media UNIQUE (project_id, media_file_id), \n\tFOREIGN KEY(project_id) REFERENCES projects (id) ON DELETE CASCADE, \n\tFOREIGN KEY(media_file_id) REFERENCES media_files (id) ON DELETE CASCADE, \n\tFOREIGN KEY(workspace_id) REFERENCES workspaces (id) ON DELETE RESTRICT\n)\n\n",
  "\nCREATE TABLE scenes (\n\tepisode_id INTEGER NOT NULL, \n\towner_id INTEGER NOT NULL, \n\t\"order\" INTEGER NOT NULL, \n\tname VARCHAR(255) NOT NULL, \n\tlocation VARCHAR(255), \n\ttime_of_day VARCHAR(64), \n\tdescription TEXT, \n\tid INTEGER NOT NULL, \n\tcreated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tupdated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tworkspace_id VARCHAR(32), \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(episode_id) REFERENCES episodes (id) ON DELETE CASCADE, \n\tFOREIGN KEY(owner_id) REFERENCES users (id) ON DELETE RESTRICT, \n\tFOREIGN KEY(workspace_id) REFERENCES workspaces (id) ON DELETE RESTRICT\n)\n\n",
  "\nCREATE TABLE script_import_sessions (\n\towner_id INTEGER NOT NULL, \n\tproject_id INTEGER, \n\tcreation_session_id INTEGER, \n\ttitle VARCHAR(255) NOT NULL, \n\tsource_name VARCHAR(255) NOT NULL, \n\tsource_text TEXT NOT NULL, \n\tsource_sha256 VARCHAR(64) NOT NULL, \n\tparser_version VARCHAR(32) NOT NULL, \n\tmaterial_type VARCHAR(32) NOT NULL, \n\tconfidence VARCHAR(16) NOT NULL, \n\treasons JSON NOT NULL, \n\tepisode_boundaries JSON NOT NULL, \n\tissues JSON NOT NULL, \n\tcorrections JSON NOT NULL, \n\tsettings JSON NOT NULL, \n\trevision INTEGER DEFAULT '0' NOT NULL, \n\tstatus VARCHAR(24) NOT NULL, \n\tconfirmation_request_id VARCHAR(100), \n\tconfirmed_at DATETIME, \n\tid INTEGER NOT NULL, \n\tcreated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tupdated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tworkspace_id VARCHAR(32), \n\tPRIMARY KEY (id), \n\tCONSTRAINT uq_script_import_confirmation_request UNIQUE (owner_id, confirmation_request_id), \n\tFOREIGN KEY(owner_id) REFERENCES users (id) ON DELETE CASCADE, \n\tFOREIGN KEY(project_id) REFERENCES projects (id) ON DELETE SET NULL, \n\tFOREIGN KEY(creation_session_id) REFERENCES creation_sessions (id) ON DELETE SET NULL, \n\tFOREIGN KEY(workspace_id) REFERENCES workspaces (id) ON DELETE RESTRICT\n)\n\n",
  "\nCREATE TABLE script_versions (\n\tepisode_id INTEGER NOT NULL, \n\trevision INTEGER NOT NULL, \n\tscript TEXT NOT NULL, \n\tcharacter_count INTEGER NOT NULL, \n\tsource VARCHAR(16) NOT NULL, \n\tnote VARCHAR(120), \n\trestored_from INTEGER, \n\tcreated_by INTEGER, \n\tcreated_at DATETIME NOT NULL, \n\tid INTEGER NOT NULL, \n\tworkspace_id VARCHAR(32), \n\tPRIMARY KEY (id), \n\tCONSTRAINT uq_script_version_revision UNIQUE (episode_id, revision), \n\tFOREIGN KEY(episode_id) REFERENCES episodes (id) ON DELETE CASCADE, \n\tFOREIGN KEY(created_by) REFERENCES users (id) ON DELETE SET NULL, \n\tFOREIGN KEY(workspace_id) REFERENCES workspaces (id) ON DELETE RESTRICT\n)\n\n",
  "\nCREATE TABLE story_continuity_facts (\n\tproject_id INTEGER NOT NULL, \n\towner_id INTEGER NOT NULL, \n\tsource_episode_id INTEGER, \n\tsource_ref VARCHAR(128) NOT NULL, \n\tsource_kind VARCHAR(32) NOT NULL, \n\tsource_revision INTEGER NOT NULL, \n\tconfirmation_status VARCHAR(16) NOT NULL, \n\tfact_type VARCHAR(32) NOT NULL, \n\tfact_key VARCHAR(255) NOT NULL, \n\tvalue JSON NOT NULL, \n\tevidence_excerpt TEXT, \n\tstatus VARCHAR(16) NOT NULL, \n\tid INTEGER NOT NULL, \n\tcreated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tupdated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tworkspace_id VARCHAR(32), \n\tPRIMARY KEY (id), \n\tCONSTRAINT uq_story_continuity_source_fact UNIQUE (project_id, source_ref, source_revision, fact_type, fact_key), \n\tFOREIGN KEY(project_id) REFERENCES projects (id) ON DELETE CASCADE, \n\tFOREIGN KEY(owner_id) REFERENCES users (id) ON DELETE RESTRICT, \n\tFOREIGN KEY(source_episode_id) REFERENCES episodes (id) ON DELETE CASCADE, \n\tFOREIGN KEY(workspace_id) REFERENCES workspaces (id) ON DELETE RESTRICT\n)\n\n",
  "\nCREATE TABLE style_presets (\n\tcategory_id INTEGER, \n\tcategory_ids JSON NOT NULL, \n\tname VARCHAR(128) NOT NULL, \n\tmodalities JSON NOT NULL, \n\tprompt_suffix TEXT NOT NULL, \n\tnegative_prompt TEXT NOT NULL, \n\tdefault_params JSON NOT NULL, \n\tpreview_media_id INTEGER, \n\treference_media_id INTEGER, \n\tenabled BOOLEAN NOT NULL, \n\tid INTEGER NOT NULL, \n\tcreated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tupdated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tworkspace_id VARCHAR(32), \n\tPRIMARY KEY (id), \n\tCONSTRAINT uq_style_presets_workspace_name UNIQUE (workspace_id, name), \n\tFOREIGN KEY(category_id) REFERENCES style_categories (id) ON DELETE SET NULL, \n\tFOREIGN KEY(preview_media_id) REFERENCES media_files (id) ON DELETE SET NULL, \n\tFOREIGN KEY(reference_media_id) REFERENCES media_files (id) ON DELETE SET NULL, \n\tFOREIGN KEY(workspace_id) REFERENCES workspaces (id) ON DELETE RESTRICT\n)\n\n",
  "\nCREATE TABLE billing_receipts (\n\tcall_id INTEGER NOT NULL, \n\tprovider_id INTEGER NOT NULL, \n\treference VARCHAR(200) NOT NULL, \n\tamount VARCHAR(100) NOT NULL, \n\tcurrency VARCHAR(8) NOT NULL, \n\tkind VARCHAR(16) NOT NULL, \n\tnote VARCHAR(1000) NOT NULL, \n\tactor_id INTEGER NOT NULL, \n\tcreated_at DATETIME NOT NULL, \n\tid INTEGER NOT NULL, \n\tworkspace_id VARCHAR(32), \n\tPRIMARY KEY (id), \n\tCONSTRAINT uq_billing_receipt_reference UNIQUE (provider_id, reference), \n\tFOREIGN KEY(call_id) REFERENCES billing_calls (id) ON DELETE RESTRICT, \n\tFOREIGN KEY(actor_id) REFERENCES users (id) ON DELETE RESTRICT, \n\tFOREIGN KEY(workspace_id) REFERENCES workspaces (id) ON DELETE RESTRICT\n)\n\n",
  "\nCREATE TABLE edit_project_receipts (\n\tedit_project_id INTEGER NOT NULL, \n\trequest_id VARCHAR(128) NOT NULL, \n\trequest_hash VARCHAR(64) NOT NULL, \n\tresponse JSON NOT NULL, \n\tid INTEGER NOT NULL, \n\tcreated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tupdated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tworkspace_id VARCHAR(32), \n\tPRIMARY KEY (id), \n\tCONSTRAINT uq_edit_project_receipts_request UNIQUE (edit_project_id, request_id), \n\tFOREIGN KEY(edit_project_id) REFERENCES edit_projects (id) ON DELETE CASCADE, \n\tFOREIGN KEY(workspace_id) REFERENCES workspaces (id) ON DELETE RESTRICT\n)\n\n",
  "\nCREATE TABLE episode_productions (\n\tepisode_id INTEGER NOT NULL, \n\tsettings JSON DEFAULT '{}' NOT NULL, \n\trevision INTEGER DEFAULT '0' NOT NULL, \n\tsource_script_revision INTEGER, \n\tscript_stale BOOLEAN DEFAULT '0' NOT NULL, \n\tscript_stale_reason TEXT, \n\tfinal_media_file_id INTEGER, \n\tactive_plan_id INTEGER, \n\tlast_error TEXT, \n\tid INTEGER NOT NULL, \n\tcreated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tupdated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tworkspace_id VARCHAR(32), \n\tPRIMARY KEY (id), \n\tCONSTRAINT uq_episode_productions_episode_id UNIQUE (episode_id), \n\tFOREIGN KEY(episode_id) REFERENCES episodes (id) ON DELETE CASCADE, \n\tFOREIGN KEY(final_media_file_id) REFERENCES media_files (id) ON DELETE SET NULL, \n\tFOREIGN KEY(active_plan_id) REFERENCES episode_production_plans (id) ON DELETE SET NULL, \n\tFOREIGN KEY(workspace_id) REFERENCES workspaces (id) ON DELETE RESTRICT\n)\n\n",
  "\nCREATE TABLE job_text_responses (\n\tjob_id INTEGER NOT NULL, \n\tcall_id INTEGER, \n\tattempt INTEGER NOT NULL, \n\tresponse_text TEXT NOT NULL, \n\tresponse_sha256 VARCHAR(64) NOT NULL, \n\tresponse_chars INTEGER NOT NULL, \n\tusage JSON NOT NULL, \n\tstreaming BOOLEAN NOT NULL, \n\tstatus VARCHAR(24) NOT NULL, \n\treceived_at DATETIME NOT NULL, \n\texpires_at DATETIME NOT NULL, \n\tprocessed_at DATETIME, \n\tprocessing_attempts INTEGER NOT NULL, \n\tlast_error_code VARCHAR(64), \n\tlast_error_message TEXT, \n\tid INTEGER NOT NULL, \n\tcreated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tupdated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tworkspace_id VARCHAR(32), \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(job_id) REFERENCES jobs (id) ON DELETE CASCADE, \n\tFOREIGN KEY(call_id) REFERENCES billing_calls (id) ON DELETE SET NULL, \n\tFOREIGN KEY(workspace_id) REFERENCES workspaces (id) ON DELETE RESTRICT\n)\n\n",
  "\nCREATE TABLE market_idea_projects (\n\tmarket_research_run_id INTEGER NOT NULL, \n\tidea_index INTEGER NOT NULL, \n\tproject_id INTEGER NOT NULL, \n\tid INTEGER NOT NULL, \n\tcreated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tupdated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tworkspace_id VARCHAR(32), \n\tPRIMARY KEY (id), \n\tCONSTRAINT uq_market_idea_projects_run_idea UNIQUE (market_research_run_id, idea_index), \n\tCONSTRAINT uq_market_idea_projects_project UNIQUE (project_id), \n\tFOREIGN KEY(market_research_run_id) REFERENCES market_research_runs (id) ON DELETE CASCADE, \n\tFOREIGN KEY(project_id) REFERENCES projects (id) ON DELETE CASCADE, \n\tFOREIGN KEY(workspace_id) REFERENCES workspaces (id) ON DELETE RESTRICT\n)\n\n",
  "\nCREATE TABLE planning_response_records (\n\tplan_id INTEGER NOT NULL, \n\trequest_id VARCHAR(128) NOT NULL, \n\tsegment_key VARCHAR(128) NOT NULL, \n\tresponse_fingerprint VARCHAR(64) NOT NULL, \n\traw_response TEXT NOT NULL, \n\tstatus VARCHAR(16) NOT NULL, \n\tdetail JSON, \n\tid INTEGER NOT NULL, \n\tcreated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tupdated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tworkspace_id VARCHAR(32), \n\tPRIMARY KEY (id), \n\tCONSTRAINT uq_planning_response_request UNIQUE (plan_id, request_id), \n\tCONSTRAINT ck_planning_response_status CHECK (status IN ('available', 'saved')), \n\tCONSTRAINT ck_planning_response_fingerprint CHECK (length(response_fingerprint) = 64), \n\tCONSTRAINT ck_planning_response_saved CHECK (status != 'saved' OR detail IS NOT NULL), \n\tFOREIGN KEY(plan_id) REFERENCES episode_planning_records (id) ON DELETE CASCADE, \n\tFOREIGN KEY(workspace_id) REFERENCES workspaces (id) ON DELETE RESTRICT\n)\n\n",
  "\nCREATE TABLE shots (\n\tscene_id INTEGER NOT NULL, \n\towner_id INTEGER NOT NULL, \n\t\"order\" INTEGER NOT NULL, \n\tduration FLOAT, \n\tshot_size VARCHAR(32), \n\tcamera_angle VARCHAR(32), \n\tcamera_movement VARCHAR(32), \n\taction TEXT, \n\tdialogue TEXT, \n\taudio_note TEXT, \n\tprompt TEXT, \n\tnegative_prompt TEXT, \n\tstatus VARCHAR(16) NOT NULL, \n\tis_locked BOOLEAN NOT NULL, \n\trefs JSON NOT NULL, \n\tid INTEGER NOT NULL, \n\tcreated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tupdated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tworkspace_id VARCHAR(32), \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(scene_id) REFERENCES scenes (id) ON DELETE CASCADE, \n\tFOREIGN KEY(owner_id) REFERENCES users (id) ON DELETE RESTRICT, \n\tFOREIGN KEY(workspace_id) REFERENCES workspaces (id) ON DELETE RESTRICT\n)\n\n",
  "\nCREATE TABLE video_segments (\n\tplan_id INTEGER NOT NULL, \n\tepisode_id INTEGER NOT NULL, \n\t\"order\" INTEGER NOT NULL, \n\tlineage_key VARCHAR(64) NOT NULL, \n\tparent_lineage_keys JSON DEFAULT '[]' NOT NULL, \n\ttitle VARCHAR(255), \n\tgeneration_duration FLOAT NOT NULL, \n\ttimeline_duration FLOAT NOT NULL, \n\ttrim_in FLOAT DEFAULT '0' NOT NULL, \n\ttrim_out FLOAT DEFAULT '0' NOT NULL, \n\tprompt TEXT NOT NULL, \n\tnegative_prompt TEXT, \n\tparameters JSON DEFAULT '{}' NOT NULL, \n\trefs JSON DEFAULT '{}' NOT NULL, \n\tstatus VARCHAR(16) DEFAULT 'pending' NOT NULL, \n\tid INTEGER NOT NULL, \n\tcreated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tupdated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tworkspace_id VARCHAR(32), \n\tPRIMARY KEY (id), \n\tCONSTRAINT uq_video_segments_plan_order UNIQUE (plan_id, \"order\"), \n\tFOREIGN KEY(plan_id) REFERENCES episode_production_plans (id) ON DELETE CASCADE, \n\tFOREIGN KEY(episode_id) REFERENCES episodes (id) ON DELETE CASCADE, \n\tFOREIGN KEY(workspace_id) REFERENCES workspaces (id) ON DELETE RESTRICT\n)\n\n",
  "\nCREATE TABLE asset_usages (\n\tproject_id INTEGER NOT NULL, \n\tasset_id INTEGER NOT NULL, \n\tepisode_id INTEGER, \n\tscene_id INTEGER, \n\tshot_id INTEGER, \n\tasset_version_id INTEGER, \n\tusage_type VARCHAR(32) NOT NULL, \n\tid INTEGER NOT NULL, \n\tcreated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tupdated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tworkspace_id VARCHAR(32), \n\tPRIMARY KEY (id), \n\tCONSTRAINT uq_asset_usages_shot UNIQUE (asset_id, shot_id, usage_type), \n\tFOREIGN KEY(project_id) REFERENCES projects (id) ON DELETE CASCADE, \n\tFOREIGN KEY(asset_id) REFERENCES assets (id) ON DELETE CASCADE, \n\tFOREIGN KEY(episode_id) REFERENCES episodes (id) ON DELETE CASCADE, \n\tFOREIGN KEY(scene_id) REFERENCES scenes (id) ON DELETE CASCADE, \n\tFOREIGN KEY(shot_id) REFERENCES shots (id) ON DELETE CASCADE, \n\tFOREIGN KEY(asset_version_id) REFERENCES asset_versions (id) ON DELETE SET NULL, \n\tFOREIGN KEY(workspace_id) REFERENCES workspaces (id) ON DELETE RESTRICT\n)\n\n",
  "\nCREATE TABLE segment_script_snapshots (\n\tsegment_id INTEGER NOT NULL, \n\tfingerprint VARCHAR(64) NOT NULL, \n\tcontent JSON NOT NULL, \n\tid INTEGER NOT NULL, \n\tcreated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tupdated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tworkspace_id VARCHAR(32), \n\tPRIMARY KEY (id), \n\tCONSTRAINT uq_segment_script_fingerprint UNIQUE (segment_id, fingerprint), \n\tFOREIGN KEY(segment_id) REFERENCES video_segments (id) ON DELETE CASCADE, \n\tFOREIGN KEY(workspace_id) REFERENCES workspaces (id) ON DELETE RESTRICT\n)\n\n",
  "\nCREATE TABLE shot_video_versions (\n\tshot_id INTEGER NOT NULL, \n\tmedia_file_id INTEGER NOT NULL, \n\tsource_job_id INTEGER, \n\tversion INTEGER NOT NULL, \n\tprompt TEXT NOT NULL, \n\tnegative_prompt TEXT, \n\tparameters JSON NOT NULL, \n\tis_final BOOLEAN NOT NULL, \n\tid INTEGER NOT NULL, \n\tcreated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tupdated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tworkspace_id VARCHAR(32), \n\tPRIMARY KEY (id), \n\tCONSTRAINT uq_shot_video_versions_version UNIQUE (shot_id, version), \n\tFOREIGN KEY(shot_id) REFERENCES shots (id) ON DELETE CASCADE, \n\tFOREIGN KEY(media_file_id) REFERENCES media_files (id) ON DELETE RESTRICT, \n\tFOREIGN KEY(source_job_id) REFERENCES jobs (id) ON DELETE SET NULL, \n\tFOREIGN KEY(workspace_id) REFERENCES workspaces (id) ON DELETE RESTRICT\n)\n\n",
  "\nCREATE TABLE video_segment_shots (\n\tsegment_id INTEGER NOT NULL, \n\tshot_id INTEGER NOT NULL, \n\t\"order\" INTEGER NOT NULL, \n\tstart_time FLOAT NOT NULL, \n\tend_time FLOAT NOT NULL, \n\tid INTEGER NOT NULL, \n\tcreated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tupdated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tworkspace_id VARCHAR(32), \n\tPRIMARY KEY (id), \n\tCONSTRAINT uq_video_segment_shots_shot UNIQUE (segment_id, shot_id), \n\tCONSTRAINT uq_video_segment_shots_order UNIQUE (segment_id, \"order\"), \n\tFOREIGN KEY(segment_id) REFERENCES video_segments (id) ON DELETE CASCADE, \n\tFOREIGN KEY(shot_id) REFERENCES shots (id) ON DELETE CASCADE, \n\tFOREIGN KEY(workspace_id) REFERENCES workspaces (id) ON DELETE RESTRICT\n)\n\n",
  "\nCREATE TABLE segment_video_versions (\n\tsegment_id INTEGER NOT NULL, \n\tmedia_file_id INTEGER NOT NULL, \n\tsource_job_id INTEGER, \n\tlegacy_shot_video_version_id INTEGER, \n\tversion INTEGER NOT NULL, \n\tprompt TEXT NOT NULL, \n\tnegative_prompt TEXT, \n\tparameters JSON DEFAULT '{}' NOT NULL, \n\tis_final BOOLEAN DEFAULT '0' NOT NULL, \n\tid INTEGER NOT NULL, \n\tcreated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tupdated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tworkspace_id VARCHAR(32), \n\tPRIMARY KEY (id), \n\tCONSTRAINT uq_segment_video_versions_version UNIQUE (segment_id, version), \n\tCONSTRAINT uq_segment_video_versions_legacy UNIQUE (legacy_shot_video_version_id), \n\tFOREIGN KEY(segment_id) REFERENCES video_segments (id) ON DELETE CASCADE, \n\tFOREIGN KEY(media_file_id) REFERENCES media_files (id) ON DELETE RESTRICT, \n\tFOREIGN KEY(source_job_id) REFERENCES jobs (id) ON DELETE SET NULL, \n\tFOREIGN KEY(legacy_shot_video_version_id) REFERENCES shot_video_versions (id) ON DELETE SET NULL, \n\tFOREIGN KEY(workspace_id) REFERENCES workspaces (id) ON DELETE RESTRICT\n)\n\n",
